import { useState, useCallback } from "react";
import { useLocation } from "wouter";
import AppHeader from "@/pages/AppHeader";
import HeroSection from "@/pages/HeroSection";
import ServicesWeOfferSection from "@/pages/ServicesWeOfferSection";
import SpotlightFeaturesSection from "@/pages/SpotlightSection";
import SmartMenuConciergeSection from "@/pages/SmartMenuSection";
import FloatingNav from "@/pages/FloatingNav";
import ContinueOrderBanner from "@/pages/ContinueOrderBanner";
import NoServicePage from "@/pages/NoServicePage";
import { useToast } from "@/hooks/use-toast";
import { PageWithLoader } from "@/components/PageWithLoader";

export default function Home() {
  const [, setLocation] = useLocation();
  const [cartCount, setCartCount] = useState(0);
  const [activeTab, setActiveTab] = useState<"home" | "menu" | "profile">("home");
  const [serviceUnavailable, setServiceUnavailable] = useState(false);
  const [currentLocationLabel, setCurrentLocationLabel] = useState("Select Address");
  const { toast } = useToast();

  const handleServiceAvailabilityChange = useCallback((isUnavailable: boolean, locationLabel: string) => {
    setServiceUnavailable(isUnavailable);
    setCurrentLocationLabel(locationLabel);
  }, []);

  const handleLocationClick = () => {
    console.log("Location selector clicked");
    setLocation("/location");
  };

  const handleCartClick = () => {
    console.log("Cart clicked");
    toast({
      title: "Cart",
      description: `You have ${cartCount} item${cartCount !== 1 ? 's' : ''} in your cart`,
    });
  };

  const handleExploreMenu = () => {
    console.log("Explore Menu clicked");
    setActiveTab("menu");
    setLocation("/explore-menu");
  };

  const handleServiceClick = (serviceId: string) => {
    console.log(`Service clicked: ${serviceId}`);

    if (serviceId === "corporate") {
      setLocation("/corporate");
    } else if (serviceId === "catering") {
      setLocation("/catering");
    } else if (serviceId === "mealbox") {
      setLocation("/mealbox");
    } else if (serviceId === "bulk") {
      // Redirect to bulk meals page
      setLocation("/bulk-meals");
    } else {
      toast({
        title: "Service Selected",
        description: `Opening ${serviceId} page...`,
      });
    }
  };

  const handleTabChange = (tab: "home" | "menu" | "profile") => {
    console.log(`Tab changed to: ${tab}`);
    setActiveTab(tab);

    if (tab === "menu") {
      setLocation("/menu");
    } else if (tab === "profile") {
      setLocation("/profile");
    }
  };

  const handleTryMenuConcierge = () => {
    console.log("AI Menu Planner clicked");
    setLocation("/concierge");
  };

  if (serviceUnavailable) {
    return (
      <NoServicePage 
        onLocationClick={handleLocationClick}
        locationLabel={currentLocationLabel}
      />
    );
  }

  return (
    <PageWithLoader>
      <div className="min-h-screen pb-44 bg-white">
        <AppHeader 
          onLocationClick={handleLocationClick}
          onServiceAvailabilityChange={handleServiceAvailabilityChange}
        />

        <HeroSection onExploreMenu={handleExploreMenu} />
        <ServicesWeOfferSection onServiceClick={handleServiceClick} />

        <div className="mt-4">
          <SpotlightFeaturesSection />
        </div>

        <div className="mt-6 mb-4">
          <SmartMenuConciergeSection onTryNow={handleTryMenuConcierge} />
        </div>

        <ContinueOrderBanner />
        <FloatingNav activeTab={activeTab} onTabChange={handleTabChange} />
      </div>
    </PageWithLoader>
  );
}

