                {/* NON-VEG Quantity */}
                <div className="flex items-center gap-3">
                  <div
                    className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                      mealPreference === "non-veg"
                        ? "border-primary"
                        : "border-muted-foreground"
                    }`}
                  >
                    {mealPreference === "non-veg" && (
                      <div className="w-3 h-3 rounded-full bg-primary" />
                    )}
                  </div>
                  <Input
