  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { Phone, Mail, MapPin, Clock, ArrowLeft } from "lucide-react";
import { useState } from "react";
import { useLocation } from "wouter";

export default function HelpPage() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useState('help');
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    bestTimeToCall: '',
    message: ''
  });

  const handleTabChange = (tab: string) => {
    setActiveTab(tab);
    if (tab === 'home') {
      setLocation('/');
    } else if (tab === 'categories') {
      setLocation('/categories/tiffins');
    } else if (tab === 'orders') {
      setLocation('/orders');
    } else if (tab === 'profile') {
      setLocation('/profile');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.bestTimeToCall) {
      toast({
        title: "Missing Information",
        description: "Please select your preferred time to call.",
        variant: "destructive"
      });
      return;
    }

    toast({
      title: "Request Submitted",
      description: "We'll get back to you soon!",
    });
    setFormData({ name: '', phone: '', bestTimeToCall: '', message: '' });
  };

  return (
    <div className="min-h-screen bg-white pb-20">
      <main className="max-w-4xl mx-auto px-4 py-8 pt-12">
        <Button 
          variant="ghost" 
          size="sm" 
