                          className="text-[10px] h-5 px-2 font-medium"
                        >
                          {count}
                        </Badge>
                      </div>
              </button>
                  );
                })}
              </div>
            </aside>

            {/* Right Content - Dishes Grid */}
            <div className="flex-1 px-3 md:px-4 py-4 md:py-6 min-w-0 overflow-y-auto overflow-x-hidden pb-20 md:pb-6">
