import "dotenv/config";
import express, { type Request, Response, NextFunction } from "express";
import cors from "cors";
import session from "express-session";
import connectPgSimple from "connect-pg-simple";
import { registerRoutes } from "./routes";
import { setupVite, serveStatic, log } from "./vite";

const app = express();

// CORS configuration - allow all in development, restrict in production
app.use(cors({
  origin: (origin, callback) => {
    // In development: allow all origins for easier development
    if (process.env.NODE_ENV !== 'production') {
      return callback(null, true);
    }

    // In production: allow from configured list and Capacitor scheme
    // FRONTEND_URLS can be a comma-separated list of origins
    const configured = (process.env.FRONTEND_URLS || process.env.FRONTEND_URL || '')
      .split(',')
      .map((o) => o.trim())
      .filter(Boolean);

    const defaultAllowed = new Set<string>([
      'capacitor://localhost',
      'ionic://localhost',
    ]);

    if (!origin) {
      // Some native requests may not send an Origin; allow in production
      return callback(null, true);
    }

    if (defaultAllowed.has(origin) || configured.includes(origin)) {
      return callback(null, true);
    }

    console.error(`CORS blocked origin: ${origin}`);
    callback(new Error('Not allowed by CORS'));
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'Accept', 'X-Requested-With'],
  preflightContinue: false,
  optionsSuccessStatus: 204
}));

app.use(express.json());
app.use(express.urlencoded({ extended: false }));

// Setup session management with PostgreSQL store (fallback to memory store if connection fails)
const PgSession = connectPgSimple(session);
const databaseUrl = process.env.SUPABASE_DATABASE_URL || process.env.DATABASE_URL;

let sessionStore: any = undefined;

if (databaseUrl) {
  try {
    sessionStore = new PgSession({
      conString: databaseUrl,
      createTableIfMissing: true,
      tableName: 'session', // Optional: specify table name
    });
    console.log("✅ Session store: Using PostgreSQL");
  } catch (error) {
    console.warn("⚠️  Failed to initialize PostgreSQL session store, using memory store:", error);
    sessionStore = undefined; // Will use memory store
  }
} else {
  console.warn("⚠️  No database URL for session store, using memory store");
}

app.use(
  session({
    store: sessionStore, // undefined = memory store
    secret: process.env.SESSION_SECRET || 'feast-express-secret-key-change-in-production',
    resave: false,
    saveUninitialized: false,
    cookie: {
      secure: process.env.NODE_ENV === 'production',
      httpOnly: true,
      sameSite: process.env.NODE_ENV === 'production' ? 'strict' : 'lax', // CSRF protection
      maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
    },
  })
);

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  const server = await registerRoutes(app);

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    // Don't send response if headers were already sent
    if (res.headersSent) {
      console.error("❌ Error after response sent:", err);
      return;
    }

    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    console.error("❌ Express error handler:", { status, message, error: err });
    res.status(status).json({ message });
  });

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get("env") === "development") {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // ALWAYS serve the app on the port specified in the environment variable PORT
  // Other ports are firewalled. Default to 3000 if not specified.
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = parseInt(process.env.PORT || '3000', 10);
  const listenOptions: any = {
    port,
  };

  // Use 0.0.0.0 to allow external connections (mobile devices on same network)
  // This works on macOS, Linux, and Windows
  listenOptions.host = '0.0.0.0';

  // reusePort is only supported on Linux
  if (process.platform === 'linux') {
    listenOptions.reusePort = true;
  }

  server.listen(listenOptions, () => {
    log(`serving on port ${port} (${listenOptions.host})`);
  });
})();

