    nickname: "HDFC",
    cardType: "mastercard"
  },
  {
    id: "2",
    cardNumber: "1234567890125678",
    validThrough: "06/26",
    cvv: "456",
    nameOnCard: "Rahul Krishna",
    nickname: "AXIS",
    cardType: "visa"
