                className="w-full"
                size="lg"
                disabled={sendOtpMutation.isPending || checkPhoneMutation.isPending}
                onClick={() => {
                  console.log('🖱️ Send OTP button clicked!');
                  console.log('📱 Phone value:', phone);
                  console.log('👤 Username value:', username);
                }}
              >
                {sendOtpMutation.isPending || checkPhoneMutation.isPending
                  ? "Sending..."
                  : "Send OTP"}
              </Button>
            </form>
          ) : (
            <form onSubmit={handleOtpSubmit} className="space-y-6">
              <div className="space-y-4">
                <div className="text-center">
                  <CheckCircle className="w-16 h-16 text-green-500 mx-auto mb-2" />
                  <p className="text-sm text-gray-600">
                    OTP sent to <span className="font-semibold">+91 {phone || 'your phone'}</span>
                  </p>
                  {phone && phone.length === 10 && (
                    <p className="text-xs text-gray-500 mt-1">
                      {phone.slice(0, 5)} {phone.slice(5)}
                    </p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="otp" className="text-sm font-medium block text-center">
                    Enter 6-Digit OTP
                  </Label>
                  <div className="flex justify-center">
                    <Input
                      id="otp"
                      data-testid="input-otp"
                      type="text"
                      inputMode="numeric"
                      placeholder="000000"
                      value={otp}
                      onChange={(e) => setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))}
                      maxLength={6}
                      className="w-48 text-center text-2xl tracking-widest font-semibold"
                      disabled={verifyOtpMutation.isPending}
                    />
                  </div>
                </div>

                <div className="text-center">
                  <Button
                    data-testid="button-resend-otp"
                    type="button"
                    variant="ghost"
                    onClick={handleResendOtp}
                    disabled={sendOtpMutation.isPending}
                    className="text-sm text-orange-600"
                  >
                    Didn't receive code? Resend
                  </Button>
                </div>
              </div>

              <div className="space-y-2">
                <Button
                  data-testid="button-verify-otp"
                  type="submit"
                  className="w-full"
                  size="lg"
                  disabled={verifyOtpMutation.isPending || otp.length !== 6}
                >
                  {verifyOtpMutation.isPending ? "Verifying..." : "Verify & Continue"}
                </Button>

                <Button
                  data-testid="button-back"
                  type="button"
                  variant="outline"
                  className="w-full"
                  onClick={() => {
                    setStep("phone");
                    setOtp("");
                  }}
                  disabled={verifyOtpMutation.isPending}
                >
                  Change Phone Number
                </Button>
              </div>
            </form>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

