                )}
                style={{ fontFamily: "Sweet Sans Pro" }}
                data-testid="filter-dietary-egg"
              >
                <Egg className="w-2.5 h-2.5" />
                Egg
              </button>
              <button
                onClick={() => setDietaryMode('non-veg')}
                className={cn(
