export const sixtyMinBulkOrderService = {
  /**
   * Create a new 60-min Bulk Meal order
   */
  async create(orderData: {
    items: Array<{ dishId: string; quantity: number; price: number }>;
    selectedAddons?: string[];
    subtotal: number;
    gst: number;
    platformFee: number;
    packagingFee: number;
