                  if (saveAddressForFuture && !validAddressId && addressLine1) {
                    try {
                      const fullAddress = [addressLine1, addressLine2, city, addressState, pincode].filter(Boolean).join(', ');
                      await addressService.create({
                        label: "Saved Address",
                        address: fullAddress,
                        landmark: addressLine2 || undefined,
                        isDefault: false,
                      });
                      toast({
                        title: "Address Saved",
                        description: "Your address has been saved for future use.",
                      });
                    } catch (err) {
                      console.error("Failed to save address:", err);
                    }
                  }

                  // Create order - use 60-min service if accessed from ExploreMenuPage (onNavigate passed)
                  const isSixtyMinOrder = !!onNavigate;

                  // Build delivery address text for 60-min orders
                  let deliveryAddressText: string | undefined = undefined;
                  if (isSixtyMinOrder && !validAddressId && addressLine1) {
                    deliveryAddressText = [addressLine1, addressLine2, city, addressState, pincode].filter(Boolean).join(', ');
                  }

                  // Calculate delivery fee for order record (use existing baseDeliveryCharges from line 4944)
                  const deliveryFeeCharged = appliedCoupon?.isFreeDelivery ? 0 : baseDeliveryCharges;
                  const discountApplied = appliedCoupon?.isFreeDelivery 
                    ? baseDeliveryCharges 
                    : (appliedCoupon?.discount || 0);

                  if (isSixtyMinOrder) {
                    await sixtyMinMealboxOrderService.create({
                      portions: `${selectedPortions}-portions`,
                      mealPreference: mealPreference,
                      selectedMealType: selectedMealType,
                      vegBoxes: vegCount,
                      eggBoxes: eggCount,
                      nonVegBoxes: nonVegCount,
                      vegPlateSelections: vegPlateSelections,
                      eggPlateSelections: eggPlateSelections,
                      nonVegPlateSelections: nonVegPlateSelections,
                      selectedAddons: selectedAddOns,
                      subtotal: subtotal,
                      deliveryFee: deliveryFeeCharged,
                      tax: gst,
                      total: total,
                      deliveryDate: deliveryDate || undefined,
                      deliveryTime: deliveryTime || undefined,
                      addressId: validAddressId,
                      deliveryAddress: deliveryAddressText,
                      couponId: appliedCoupon?.id || undefined,
                      couponCode: appliedCoupon?.code || undefined,
                      discountApplied: discountApplied > 0 ? discountApplied : undefined,
                    });
                  } else {
                    await mealboxOrderService.create({
                      portions: `${selectedPortions}-portions`,
                      mealPreference: mealPreference,
                      selectedMealType: selectedMealType,
                      vegBoxes: vegCount,
                      eggBoxes: eggCount,
                      nonVegBoxes: nonVegCount,
                      vegPlateSelections: vegPlateSelections,
