                      couponCode: appliedCoupon?.code || undefined,
                      discountApplied: discountApplied > 0 ? discountApplied : undefined,
                    });
                  }

                  // Clear mealbox progress when order is placed
                  clearMealBoxProgress();

                  // Track order completed
                  const itemCount = vegCount + eggCount + nonVegCount;
                  analytics.trackOrderCompleted(
                    `mealbox-${Date.now()}`,
                    total,
                    itemCount,
                    'pending'
                  ).catch(() => {});

                  toast({
                    title: "Order Created!",
                    description: "Your MealBox order has been placed successfully.",
                  });

                  navigate("/mealbox-thank-you");
                } catch (error: any) {
                  console.error("Error creating order:", error);
                  toast({
                    variant: "destructive",
                    title: "Order Failed",
                    description: error.message || "Failed to create order. Please try again.",
                  });
                } finally {
                  setIsCreatingOrder(false);
                }
              }}
              disabled={isCreatingOrder}
              className="w-full py-6 text-lg font-semibold border-0 flex items-center justify-between"
              style={{
                fontFamily: "Sweet Sans Pro",
                backgroundColor: "#1A9952",
