          <Button
            onClick={() => navigate("/bulk-meals-cart")}
            className="px-4 py-1.5 text-sm font-semibold border-0 min-h-0 h-auto"
            style={{
              fontFamily: "Sweet Sans Pro",
              backgroundColor: "white",
              color: "#1A9952",
              borderRadius: "6px"
            }}
            data-testid="button-view-cart"
          >
            View Cart →
          </Button>
        </div>,
        document.body
