              </div>

              <Slider
                value={priceRange}
                onValueChange={(value) => setPriceRange(value as [number, number])}
                min={0}
                max={500}
                step={10}
                className="w-full"
                data-testid="slider-price-range"
              />

              <div className="flex justify-between text-xs text-muted-foreground">
                <span>₹0</span>
                <span>₹200+</span>
              </div>
            </div>
