                      <img src={uttapamImage} alt="Uttapam" className="w-full h-24 object-cover rounded-md mb-2" />
                      <p className="text-sm font-medium">Uttapam</p>
                      <p className="text-xs text-muted-foreground">Thick savory pancake</p>
